const CACHE_VERSION="v3",CACHE_NAME="class-score-system-v3",ASSETS_TO_CACHE=["index.html","style.min.css","script.min.js"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>(console.log("Opened cache"),e.addAll(ASSETS_TO_CACHE))).then(()=>(self.clients.matchAll().then(e=>{e.forEach(e=>{e.postMessage({type:"SW_UPDATED",message:"新版本已就绪，请刷新页面以使用最新版本"})})}),self.skipWaiting())))}),self.addEventListener("activate",e=>{const t=[CACHE_NAME];e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(-1===t.indexOf(e))return caches.delete(e)}))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{e.respondWith((async()=>{try{try{const t=await fetch(e.request,{cache:"no-store"});if(t&&200===t.status&&"basic"===t.type){const s=t.clone(),a=await caches.open(CACHE_NAME);await a.put(e.request,s)}return t}catch(t){const s=await caches.match(e.request);return s||new Response("Network error occurred",{status:408,statusText:"Request Timeout"})}}catch(e){return new Response("Service Worker error occurred",{status:500,statusText:"Internal Server Error"})}})())}),self.addEventListener("message",e=>{e.data&&"SKIP_WAITING"===e.data.type&&self.skipWaiting()});